from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')

s=s.replace('<title>3DLite v3.99.1 LiteTrace Fast Mode</title>', '<title>3DLite v3.99.2 LiteTrace Fast Telemetry</title>')
s=s.replace("window.ThreeDLiteVersion='3.99.1';", "window.ThreeDLiteVersion='3.99.2';")

# Insert telemetry immediately before the known LiteTrace Fast final-stat write. This avoids coupling to formatting of its public API block.
stat_anchor='      LiteTraceFastRuntime3991.lastStats=fastStats;'
if stat_anchor not in s: raise SystemExit('LiteTrace Fast stats anchor missing')
telemetry="""  const LiteTraceFastTelemetry3992={\n    version:'3.99.2',schema:1,history:[],last:null,\n    finishJob(job){\n      if(!job)return null; const fast=job.liteTraceFast&&typeof job.liteTraceFast==='object'?job.liteTraceFast:null; if(!fast)return null;\n      const width=Math.max(1,Number(job.width)||1),height=Math.max(1,Number(job.height)||1),elapsedMs=Math.max(0,Number(job.elapsedMs)||0),completedPixels=Math.max(0,Number(job.completedPixels)||0);\n      const rayBudget=Math.max(0,Number(fast.rayBudget)||0),sampleBudget=Math.max(0,Number(fast.sampleBudget)||0);\n      const entry={schema:1,version:'3.99.2',renderer:'litetrace',mode:'fast',jobId:job.id||null,status:job.status||'unknown',width,height,elapsedMs,completedPixels,megapixels:(width*height)/1000000,pixelsPerMs:elapsedMs>0?completedPixels/elapsedMs:0,raysPerMs:elapsedMs>0?rayBudget/elapsedMs:0,samplesPerMs:elapsedMs>0?sampleBudget/elapsedMs:0,spp:Math.max(1,Number(fast.spp)||1),maxDepth:Math.max(1,Number(fast.maxDepth)||1),rayBudget,sampleBudget,hitCount:Math.max(0,Number(fast.hitCount)||0),missCount:Math.max(0,Number(fast.missCount)||0),primaryRays:Math.max(0,Number(fast.primaryRays)||0),secondaryRays:Math.max(0,Number(fast.secondaryRays)||0),shadowRays:Math.max(0,Number(fast.shadowRays)||0),reflectionRays:Math.max(0,Number(fast.reflectionRays)||0),refractionRays:Math.max(0,Number(fast.refractionRays)||0),terminatedPaths:Math.max(0,Number(fast.terminatedPaths)||0),reflectionCap:Math.max(0,Number(fast.reflectionCap)||0),shadowRayCap:Math.max(0,Number(fast.shadowRayCap)||0),maxSecondaryRays:Math.max(0,Number(fast.maxSecondaryRays)||0),maxShadowRays:Math.max(0,Number(fast.maxShadowRays)||0),denoiseStrength:Number(fast.denoiseStrength)||0,finishedAt:Number(job.finishedAt)||performance.now()};\n      entry.hitRate=(entry.hitCount+entry.missCount)>0?entry.hitCount/(entry.hitCount+entry.missCount):0; entry.secondaryShare=entry.rayBudget>0?entry.secondaryRays/entry.rayBudget:0; entry.shadowShare=entry.rayBudget>0?entry.shadowRays/entry.rayBudget:0; entry.reflectionShare=entry.rayBudget>0?entry.reflectionRays/entry.rayBudget:0; entry.refractionShare=entry.rayBudget>0?entry.refractionRays/entry.rayBudget:0;\n      this.last=entry;this.history.push(entry);if(this.history.length>24)this.history.splice(0,this.history.length-24);\n      try{if(window.ThreeDLiteL3NAdaptiveRender3990&&typeof window.ThreeDLiteL3NAdaptiveRender3990.observe==='function')window.ThreeDLiteL3NAdaptiveRender3990.observe({renderer:'litetrace-fast',renderTimeMs:elapsedMs,rays:rayBudget,samples:sampleBudget,qualityGain:0,noise:0,efficiency:elapsedMs>0?completedPixels/elapsedMs:0,metadata:{liteTraceFast:{...entry}}});}catch(e){console.warn('[3DLite LiteTrace Fast Telemetry] adaptive observe',e);}\n      return {...entry};\n    },getLast(){return this.last?{...this.last}:null;},getHistory(){return this.history.map(x=>({...x}));},reset(){this.history.length=0;this.last=null;return true;}\n  };\n  window.__3DLiteLiteTraceFastTelemetry3992=true; window.ThreeDLiteLiteTraceFastTelemetry3992=LiteTraceFastTelemetry3992;\n\n"""
# Put controller once, immediately before the containing renderer function's final stats section.
pos=s.find(stat_anchor)
line_start=s.rfind('\n',0,pos)+1
s=s[:line_start]+telemetry+s[line_start:]

old="""      LiteTraceFastRuntime3991.lastStats=fastStats;\n      job.liteTraceFast=fastStats;\n      job.rayBudget=fastStats.rayBudget;\n      job.sampleBudget=fastStats.sampleBudget;\n"""
new="""      LiteTraceFastRuntime3991.lastStats=fastStats;\n      job.liteTraceFast={...fastStats};\n      job.rayBudget=fastStats.rayBudget;\n      job.sampleBudget=fastStats.sampleBudget;\n      try{if(window.ThreeDLiteLiteTraceFastTelemetry3992&&typeof window.ThreeDLiteLiteTraceFastTelemetry3992.finishJob==='function'){const telemetryJob={...job,status:'complete',finishedAt:performance.now()};telemetryJob.elapsedMs=Math.max(0,telemetryJob.finishedAt-(Number(job.startedAt)||telemetryJob.finishedAt));window.ThreeDLiteLiteTraceFastTelemetry3992.finishJob(telemetryJob);}}catch(e){console.warn('[3DLite LiteTrace Fast Telemetry] finishJob',e);}\n"""
if old not in s: raise SystemExit('LiteTrace Fast job stats block missing')
s=s.replace(old,new,1)
for required in ["window.ThreeDLiteVersion='3.99.2';",'ThreeDLiteLiteTraceFastTelemetry3992',"renderer:'litetrace-fast'",'raysPerMs','samplesPerMs']:
    if required not in s: raise SystemExit('missing '+required)
p.write_text(s,encoding='utf-8')
print('patched v3.99.2 LiteTrace Fast telemetry wiring')
